      "code": "curl --location --request PATCH 'http://api.vtexinternal.com/api/rns/subscriptions-group/734D48BE8D6350A2810A520B3AC6919B?an=recorrenciaqa' \
--header 'Content-Type: application/json' \
--header 'Content-Type: text/plain' \
--data-raw '{
    "item": [
